(function () {
  'use strict';
  const data = FORGE_ART_DATA;
  const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const normalize = name => String(name || '').toLocaleLowerCase('ru').replaceAll('ё','е').trim();
  function entry(name) { return data.exercises[normalize(name)] || null; }
  function personal(name) { return typeof state !== 'undefined' ? state.n9UserPhotos?.[name] : null; }
  function source(name) { return personal(name) || entry(name)?.frames[0] || null; }
  function missingData(name) { return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 180"><rect width="200" height="180" rx="20" fill="#17272b"/><text x="100" y="88" text-anchor="middle" fill="#b6c8c8" font-family="sans-serif" font-size="14">Своё упражнение</text><text x="100" y="112" text-anchor="middle" fill="#86a2a4" font-family="sans-serif" font-size="12">Добавьте рисунок</text></svg>'); }
  function thumb(name) { return `<img class="forge-exercise-art" loading="lazy" decoding="async" src="${escape(source(name) || missingData(name))}" alt="${escape(name)}">`; }
  function muscle(group) {
    const art = window.ForgeArtStandards.muscleGroup(group);
    return art
      ? `<img class="forge-muscle-art vs-anatomy-thumb" data-art-type="MUSCLE_GROUP_ART" data-muscle-id="${escape(art.id)}" src="${escape(art.file)}" alt="${escape(art.group)} — анатомия" width="112" height="126" loading="lazy">`
      : '<span class="forge-custom-muscle" aria-hidden="true">＋</span>';
  }
  function picture(name) {
    const item=entry(name),custom=personal(name);const frames=custom?[custom]:(item?.frames||[]);
    if(!frames.length)return `<div class="forge-art-empty"><b>${escape(name)}</b><p>Добавьте свой рисунок в карточку упражнения.</p></div>`;
    return `<div class="forge-art-gallery"><div class="forge-art-frames">${frames.map((src,i)=>`<figure><img src="${escape(src)}" alt="${escape(name)} — положение ${i+1}" decoding="async"><figcaption>${frames.length>1?'Положение '+(i+1):'Мой рисунок'}</figcaption></figure>`).join('')}</div><div class="forge-art-caption">${custom?'Мой рисунок':item.kind==='schematic'?'Схема движения':'Иллюстрация движения'} · ${escape(name)}</div></div>`;
  }
  function groupChoices(groups,choose) {return `<div class="forge-muscle-choices">${groups.filter(g=>g!=='Все').map(g=>`<button type="button" onclick="${choose}('${encodeURIComponent(g)}')">${muscle(g)}<b>${escape(g)}</b></button>`).join('')}</div>`;}
  window.ForgeArt={entry,source,thumb,muscle,picture,missingData,groupChoices,registry:data};
})();
